import{_ as o,o as r,c as i,a3 as t}from"./chunks/framework.DACwFHq9.js";const u=JSON.parse('{"title":"Screen Capture & Video Recording","description":"Capture screen areas and record video walk-throughs with custom source selection and auto-minimize.","frontmatter":{"title":"Screen Capture & Video Recording","description":"Capture screen areas and record video walk-throughs with custom source selection and auto-minimize.","keywords":"screen capture, screenshot, screen recording, video recording, window picker, overlay controls, markdown video","category":"Workspace"},"headers":[],"relativePath":"workspace/screen-capture.md","filePath":"workspace/screen-capture.md","lastUpdated":1787158574000}'),a={name:"workspace/screen-capture.md"};function n(s,e,l,c,d,g){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="screen-capture-video-recording" tabindex="-1">Screen Capture &amp; Video Recording <a class="header-anchor" href="#screen-capture-video-recording" aria-label="Permalink to &quot;Screen Capture &amp; Video Recording&quot;">​</a></h1><p>Notely supports both static screen area capture (snipping) and full screen/application window video recording directly into your notes.</p><hr><h2 id="_1-static-screen-capture" tabindex="-1">1. Static Screen Capture <a class="header-anchor" href="#_1-static-screen-capture" aria-label="Permalink to &quot;1. Static Screen Capture&quot;">​</a></h2><ol><li>Position your cursor in the editor where you want the image link placed.</li><li>Click the toolbar <strong>📷 Capture</strong> button or press <strong><code>Ctrl + Shift + S</code></strong>.</li><li>Select the target area using the snip overlay.</li></ol><h3 id="modes-settings-→-screen-capture" tabindex="-1">Modes (Settings → Screen Capture) <a class="header-anchor" href="#modes-settings-→-screen-capture" aria-label="Permalink to &quot;Modes (Settings → Screen Capture)&quot;">​</a></h3><ul><li><strong>Auto Insert (<code>📷 A</code>)</strong>: Inserts the captured image immediately into <code>media/</code> as a Markdown reference.</li><li><strong>Review Before Insert (<code>📷 R</code>)</strong>: Opens an image crop and annotation editor before saving.</li></ul><hr><h2 id="_2-screen-video-recording" tabindex="-1">2. Screen Video Recording <a class="header-anchor" href="#_2-screen-video-recording" aria-label="Permalink to &quot;2. Screen Video Recording&quot;">​</a></h2><p>Capture high-definition screen video recordings with audio directly into your active note.</p><h3 id="recording-workflow" tabindex="-1">Recording Workflow <a class="header-anchor" href="#recording-workflow" aria-label="Permalink to &quot;Recording Workflow&quot;">​</a></h3><ol><li>Click <strong>🎥 Record</strong> on the Markdown editor toolbar.</li><li><strong>Select Recording Source</strong>: <ul><li><strong>Screens</strong>: Choose any connected desktop display.</li><li><strong>Application Windows</strong>: Select any open application window with live thumbnail previews.</li><li><strong>Microphone Toggle</strong>: Toggle <strong>Mic: ON / OFF</strong> to capture audio commentary.</li></ul></li><li>Click <strong>Start Recording</strong>: <ul><li>Notely automatically minimizes to clear the desktop recording area.</li><li>A floating, always-on-top draggable control overlay pill appears on screen.</li></ul></li><li><strong>Recording Overlay Controls</strong>: <ul><li><strong>Timer (<code>00:00</code>)</strong>: Displays elapsed recording duration.</li><li><strong>Pause / Resume</strong>: Pause and resume video capture seamlessly.</li><li><strong>Microphone Toggle</strong>: Mute or unmute your mic mid-recording.</li><li><strong>Stop &amp; Save (<code>⏹</code>)</strong>: Stops recording, restores the Notely window, saves a <code>.webm</code> file into <code>media/recordings/</code>, and inserts the video card into your note.</li><li><strong>Cancel (<code>✕</code>)</strong>: Cancels the recording session without saving.</li></ul></li></ol><hr><h2 id="_3-video-playback-note-preview" tabindex="-1">3. Video Playback &amp; Note Preview <a class="header-anchor" href="#_3-video-playback-note-preview" aria-label="Permalink to &quot;3. Video Playback &amp; Note Preview&quot;">​</a></h2><p>Video links are rendered inside notes as interactive video cards:</p><ul><li><strong>Inline Frame Thumbnail</strong>: Shows a live visual thumbnail frame of the recording inside the note preview.</li><li><strong><code>▶ Play Video</code> Badge</strong>: Displays a centered play badge indicator over the thumbnail card.</li><li><strong>Modal Player</strong>: Clicking the video card opens a full-screen player modal featuring: <ul><li>Play, pause, volume, and playback speed controls.</li><li><strong>Copy Path</strong>: Instantly copy the video&#39;s local disk path to your clipboard.</li><li><strong>Download Video</strong>: Export or download the WebM recording file.</li></ul></li></ul>',16)])])}const h=o(a,[["render",n]]);export{u as __pageData,h as default};
